/** Where uploaded files live (docs/design.md section 11). Local disk now; S3/R2 can implement this later. */
export interface StorageDriver {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  delete(key: string): Promise<void>;
  url(key: string): string;
}

/** Keys are generated by us, never taken from the user: lowercase path segments only, no "..". */
const SAFE_KEY = /^[a-z0-9]+(?:[/._-][a-z0-9]+)*$/;

export function assertSafeKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error(`Unsafe storage key: ${key}`);
}
